package org.jlinalg.sequence;

import java.io.IOException;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class HomerSamTagsTest {
    private static final Map<String,Long> REF=Map.of("chr1",100000L);
    private static final HomerSamTags.Limits LIMITS=new HomerSamTags.Limits(10000,10000000,10000,1000);
    private static HomerSamTags.Options options(HomerSamTags.Mapping mapping,HomerSamTags.Mates mates,HomerSamTags.Length length,HomerSamTags.SoftClips clips){return new HomerSamTags.Options(mapping,mates,length,clips,30,0,1000000,false,false);}
    private static HomerSamTags.Options defaults(){return options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT);}
    private static String sam(String name,int flag,int pos,int mapq,String cigar,int tlen){return name+"\t"+flag+"\tchr1\t"+pos+"\t"+mapq+"\t"+cigar+"\t*\t0\t"+tlen+"\tACGTACGTAC\tIIIIIIIIII\n";}
    private static HomerSamTags.Summary read(String text,HomerSamTags.Options o,List<HomerSamTags.Row> rows)throws Exception{return HomerSamTags.read(new StringReader(text),REF,o,LIMITS,rows::add,()->{});}
    private static HomerSamTags.Cigar cigar(String text,char strand)throws Exception{return HomerSamTags.coordinates(text,strand,HomerSamTags.SoftClips.ORIGINAL_DEFAULT,1000);}
    @Test void sourceMatchingBlocksUseExactPlusMinusAnchors()throws Exception{assertEquals(new HomerSamTags.Cigar(0,10,false),cigar("10M",'+'));assertEquals(new HomerSamTags.Cigar(9,10,false),cigar("10M",'-'));assertEquals(new HomerSamTags.Cigar(0,10,false),cigar("10=",'+'));}
    @Test void bothOriginalSoftClipChoicesIgnoreSDespiteHelpWording()throws Exception{for(var flag:List.of(HomerSamTags.SoftClips.ORIGINAL_DEFAULT,HomerSamTags.SoftClips.ORIGINAL_RMSOFT)){assertEquals(new HomerSamTags.Cigar(0,7,false),HomerSamTags.coordinates("3S7M",'+',flag,100));assertEquals(new HomerSamTags.Cigar(6,7,false),HomerSamTags.coordinates("7M3S",'-',flag,100));}}
    @Test void sourceSplicingSelectsFirstOrLastMatchingBlock()throws Exception{assertEquals(new HomerSamTags.Cigar(0,10,false),cigar("10M100N20M",'+'));assertEquals(new HomerSamTags.Cigar(129,20,false),cigar("10M100N20M",'-'));}
    @Test void legacyInsertionHardclipPaddingAndMismatchRulesStayDistinctFromStandardSam()throws Exception{assertEquals(new HomerSamTags.Cigar(0,28,false),cigar("10M2I20M",'+'));assertEquals(new HomerSamTags.Cigar(27,28,false),cigar("10M2I20M",'-'));assertEquals(new HomerSamTags.Cigar(3,10,false),cigar("3H10M",'+'));assertEquals(new HomerSamTags.Cigar(12,10,false),cigar("3P10M",'-'));assertEquals(new HomerSamTags.Cigar(22,10,false),cigar("10M3X10M",'-'));assertEquals(new HomerSamTags.Cigar(-3,10,false),cigar("3I10M",'+'));}
    @Test void sourceOmitSnIsAnExplicitDisposition()throws Exception{for(String text:List.of("3S7M","10M100N20M"))assertTrue(HomerSamTags.coordinates(text,'+',HomerSamTags.SoftClips.OMIT_SN,100).omitted());var rows=new ArrayList<HomerSamTags.Row>();var o=options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.OMIT_SN);var s=read(sam("soft",0,300,60,"3S7M",0),o,rows);assertEquals(0,s.acceptedWeight());assertEquals(1,s.originalAllPrimaryWeight());assertEquals(HomerSamTags.Disposition.CIGAR_OMITTED,rows.get(0).disposition());}
    @Test void malformedOrUnsupportedSourceCigarsFailWithoutInventedCoordinates(){for(String text:List.of("","0M","10","M10","10X","10B","1M100I1M","1000000001M","900000000M900000000N10M"))assertThrows(Exception.class,()->cigar(text,'+'));assertThrows(IOException.class,()->HomerSamTags.coordinates("1M1M",'+',HomerSamTags.SoftClips.ORIGINAL_DEFAULT,1));}
    @Test void pairedAlignmentWeightsAreHalfEvenWithOneMateSelected()throws Exception{String text=sam("pair",99,1000,60,"10M",100)+sam("pair",147,1090,60,"10M",-100);var rows=new ArrayList<HomerSamTags.Row>();var s=read(text,defaults(),rows);assertEquals(2,s.acceptedRecords());assertEquals(1,s.acceptedWeight());assertEquals(0.5,rows.get(0).weight());var first=options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.FIRST,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT);assertEquals(0.5,read(text,first,new ArrayList<>()).acceptedWeight());}
    @Test void originalTemplateLengthAndZeroTlenFallbackAreSeparateFromCigarBlockLength()throws Exception{var rows=new ArrayList<HomerSamTags.Row>();var o=options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.PAIRED_TEMPLATE,HomerSamTags.SoftClips.ORIGINAL_DEFAULT);read(sam("template",147,1090,60,"10M",-100)+sam("soft",73,300,60,"3S7M",0),o,rows);assertEquals(new HomerSamTags.Tag("chr1",1099,'-',100),rows.get(0).tag());assertEquals(new HomerSamTags.Tag("chr1",300,'+',10),rows.get(1).tag());}
    @Test void secondaryLowMapqAndPrimaryBeforeUniquenessUseDifferentPopulations()throws Exception{var rows=new ArrayList<HomerSamTags.Row>();var s=read(sam("secondary",256,100,60,"10M",0)+sam("low",0,200,29,"10M",0)+sam("edge",0,300,30,"10M",0),defaults(),rows);assertEquals(3,s.alignmentRecords());assertEquals(1,s.acceptedWeight());assertEquals(2,s.originalAllPrimaryWeight());assertEquals(List.of(HomerSamTags.Disposition.SECONDARY_FILTER,HomerSamTags.Disposition.MAPQ_FILTER,HomerSamTags.Disposition.ACCEPTED),rows.stream().map(HomerSamTags.Row::disposition).toList());}
    @Test void sourceUniqueDoesNotSilentlyRemoveDuplicatesOrSupplementaryAlignments()throws Exception{var rows=new ArrayList<HomerSamTags.Row>();var s=read(sam("duplicate",1024,100,60,"10M",0)+sam("supplementary",2048,200,60,"10M",0),defaults(),rows);assertEquals(2,s.acceptedWeight());assertEquals(2,s.acceptedRecords());}
    @Test void keepOneAndKeepAllRetainTheirOriginalFlagAndQualityRules()throws Exception{String text=sam("secondary",256,100,60,"10M",0)+sam("low",0,200,0,"10M",0);assertEquals(1,read(text,options(HomerSamTags.Mapping.KEEP_ONE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT),new ArrayList<>()).acceptedWeight());assertEquals(2,read(text,options(HomerSamTags.Mapping.KEEP_ALL,HomerSamTags.Mates.BOTH,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT),new ArrayList<>()).acceptedWeight());}
    @Test void secondMateSelectionAlsoExcludesUnpairedRows()throws Exception{var rows=new ArrayList<HomerSamTags.Row>();var o=options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.SECOND,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT);var s=read(sam("single",0,100,60,"10M",0)+sam("pair",147,200,60,"10M",-100),o,rows);assertEquals(0.5,s.acceptedWeight());assertEquals(0.5,s.originalAllPrimaryWeight());assertEquals(HomerSamTags.Disposition.MATE_FILTER,rows.get(0).disposition());}
    @Test void lengthFilteringUsesOriginalSequenceOrTemplateBeforeCigarProjection()throws Exception{var o=new HomerSamTags.Options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.PAIRED_TEMPLATE,HomerSamTags.SoftClips.ORIGINAL_DEFAULT,30,50,200,false,false);var rows=new ArrayList<HomerSamTags.Row>();var s=read(sam("single",0,100,60,"10M",0)+sam("paired",99,1000,60,"10M",100),o,rows);assertEquals(0.5,s.acceptedWeight());assertEquals(HomerSamTags.Disposition.LENGTH_FILTER,rows.get(0).disposition());assertEquals(0.5,s.originalAllPrimaryWeight());}
    @Test void explicitFlipsPrecedeOriginalCigarAnchorSelection()throws Exception{var o=new HomerSamTags.Options(HomerSamTags.Mapping.UNIQUE,HomerSamTags.Mates.BOTH,HomerSamTags.Length.MATCHING_BLOCK,HomerSamTags.SoftClips.ORIGINAL_DEFAULT,30,0,1000,false,true);var rows=new ArrayList<HomerSamTags.Row>();read(sam("mate2",147,200,60,"10M",-100),o,rows);assertEquals(new HomerSamTags.Tag("chr1",200,'+',10),rows.get(0).tag());}
    @Test void noTagDirectoryMinimumIsInventedByNativePopulationMethod()throws Exception{var s=read(sam("one-mate",147,200,60,"10M",-100),defaults(),new ArrayList<>());assertEquals(0.5,s.acceptedWeight());assertEquals(1,s.acceptedRecords());assertEquals(1,s.dispositions().get(HomerSamTags.Disposition.ACCEPTED));assertThrows(UnsupportedOperationException.class,()->s.dispositions().clear());}
    @Test void rawRowsUnicodeNamesCrLfAndFinalNonLfLineRemainRecoverable()throws Exception{String text="@HD\tVN:1.6\r\n"+sam("rα",0,100,60,"10M",0).stripTrailing();var rows=new ArrayList<HomerSamTags.Row>();var s=read(text,defaults(),rows);assertEquals(text.length(),s.decodedCharacters());assertEquals(1,s.headerRecords());assertEquals(2,rows.get(0).sourceLine());assertEquals("rα",rows.get(0).readName());assertEquals(text.substring(text.indexOf('\n')+1),rows.get(0).sourceText());}
    @Test void missingAndInvalidMappedCoordinatesCannotBecomeCrossContigTags(){assertThrows(IOException.class,()->read(sam("x",0,100,60,"10M",0).replace("\tchr1\t","\tchrX\t"),defaults(),new ArrayList<>()));assertThrows(IOException.class,()->read(sam("x",16,100000,60,"10M",0),defaults(),new ArrayList<>()));}
    @Test void nonAsciiSequenceCannotSilentlyChangeOriginalUtf8ByteLength(){assertThrows(IOException.class,()->read(sam("x",0,100,60,"10M",0).replace("ACGTACGTAC","ACGTαCGTAC"),defaults(),new ArrayList<>()));}
    @Test void originalReservedCigarReturnCodesCannotBecomeOrdinaryNegativeOffsets(){for(String text:List.of("12345678I10M","12345679I10M"))assertThrows(IOException.class,()->cigar(text,'+'));}
    @Test void emptyMalformedCapacityAndCallerFailuresAreVisible()throws Exception{for(String text:List.of("","@HD\tVN:1.6\n","\n","bad\tfields\n",sam("x",0,100,60,"10M",0).replace("\t60\t","\t256\t")))assertThrows(IOException.class,()->read(text,defaults(),new ArrayList<>()));String text=sam("a",0,100,60,"10M",0)+sam("b",0,200,60,"10M",0);assertThrows(IOException.class,()->HomerSamTags.read(new StringReader(text),REF,defaults(),new HomerSamTags.Limits(1,10000,1000,100),r->{},()->{}));assertThrows(IOException.class,()->HomerSamTags.read(new StringReader(text),REF,defaults(),LIMITS,r->{throw new IOException("ledger bound");},()->{}));assertThrows(IOException.class,()->HomerSamTags.read(new StringReader(text),REF,defaults(),LIMITS,r->{},()->{throw new IOException("deadline");}));}
}
